// th16_s7_w01 —— TH16 Extra 道中波次：GirlA01 双侧编队
// 源：st07.ecl.txt MainSub00:1158-1172（entry）；依赖 GirlA01:131-140、
//     GirlA01_at:142-158、GirlA01_at2:160-180。
// 卡帧 = 源帧 + OPENING_BUFFER(120)：源 MainSub00 入口（源第 0 帧）对应卡帧 120。

const TH16_RICE: int = 480; // 源 etSprite(0, 8, 6)：type 8 -> TH16_RICE，色 6

const TIME_LIMIT: int = 924;
const OPENING_BUFFER: int = 120;

// 源移动角（弧度换算 BAM）：moveVel 1.3744467 rad = 78.75°；moveVelTime 目标 -1.7671459 rad = -101.25°。
// enmCreateM 给出子镜像位=1，x 速度取反等价 θ -> 180°-θ，故右侧敌用 101.25° / 180° / -78.75°。
const ANG_78_75: int = 14336;
const ANG_101_25: int = 18432;
const ANG_L101_25: int = -18432;
const ANG_180: int = 32768;
const ANG_L78_75: int = -14336;

// 源 GirlA01_at2 单发：etNew(0); etAim(0,0); etSprite(0,8,6); etCount(0,1,1);
// etAngle(0,0,3°)（单路 N=1 时 F(1,0)=0，无角偏移）; etSpeed(0,4.2,2.2)（单层取 s0=4.2）; etOn(0)。
// EX 记录0 ANIM a=1 只保留出生退位移 position -= 4*velocity；出生减速/无判定/动画等待按口径省略。
sub girl_shot() {
    var a: angle = aim_player();
    var bx: fx = $self_x - 16.8fx * cos(a);
    var by: fx = $self_y - 16.8fx * sin(a);
    _ = fire(TH16_RICE, 6, bx, by, 4.2fx, a, none, none);
}

// 源 GirlA01_at2：wait(10); $A=10; if($A--) 循环 10 次，每发后 wait(1 + RAND%20)。
async sub girl_bullets() {
    wait(10);
    for i in 0..10 {
        girl_shot();
        wait(1 + rand(20));
    }
}

// 源 GirlA01/GirlA01_at：anm*、dropMain/dropExtra/dropSeason 为纯表现与奖励，按口径省略；
// 真实敌按源设置受击/体碰框（setHurtbox(24,24)->r12、setHitbox(16,16)->r8）并保持无敌。
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn girl_bullets(); // 源 @GirlA01_at2() async

    var a0: angle = ANG_78_75 as angle;
    var a1: angle = 0deg;
    var a2: angle = ANG_L101_25 as angle;
    if mirror != 0 {
        a0 = ANG_101_25 as angle;
        a1 = ANG_180 as angle;
        a2 = ANG_L78_75 as angle;
    }
    // 源 moveVel(78.75°,3.2) 后紧跟 moveVelTime(120, mode1=二次加速, 0°, 2.0)。
    move_vel(0, a0, 3.2fx, EASE_LINEAR);
    move_vel(120, a1, 2.0fx, EASE_QUAD_IN);
    wait(120);
    // 源 moveVelTime(60, mode4=二次减速, -101.25°, 4.0)，随后进入 wait(1000) 无限循环。
    move_vel(60, a2, 4.0fx, EASE_QUAD_OUT);
    loop { wait(1000); }
}

// 源 MainSub00：wait(50); A=10; 每轮 enmCreate 左(-150+RANDF2*8)、wait(10)、
// enmCreateM 右(150+RANDF2*8)、wait(10)，共 10 轮；两处 RANDF2 各自独立取样一次。
async sub wave() {
    wait(OPENING_BUFFER);
    wait(50);
    for i in 0..10 {
        var lu: fx = (rand(65536) - 32768) as fx / 32768;
        _ = spawn_enemy(-150fx + 8fx * lu, -16fx, 50, 0, 0, 0, girl(0));
        wait(10);
        var ru: fx = (rand(65536) - 32768) as fx / 32768;
        _ = spawn_enemy(150fx + 8fx * ru, -16fx, 50, 0, 0, 0, girl(1));
        wait(10);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
